// Bundles xterm.js into one self-contained HTML string for the terminal WebView (works offline, no CDN).
// Runs on postinstall and before `expo start`; the output is git-ignored.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (id) => readFileSync(require.resolve(id), 'utf8');
// A literal "</script" inside inline JS would end the element early.
const js = (src) => src.replace(/<\/script/gi, '<\\/script').replace(/\/\/# sourceMappingURL=.*$/gm, '');

const bridge = readFileSync(join(root, 'src/ui/terminal-bridge.js'), 'utf8');
const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover">
<style>${read('@xterm/xterm/css/xterm.css')}
html, body { margin: 0; height: 100%; background: #0d1014; overflow: hidden; overscroll-behavior: none; -webkit-text-size-adjust: 100%; }
#t { position: absolute; top: 0; right: 0; bottom: 0; left: 0; padding: 4px 2px 0 6px; }
.xterm .xterm-viewport { background-color: transparent !important; }
</style>
</head>
<body>
<div id="t"></div>
<script>${js(read('@xterm/xterm/lib/xterm.js'))}</script>
<script>${js(read('@xterm/addon-fit/lib/addon-fit.js'))}</script>
<script>${js(bridge)}</script>
</body>
</html>`;

writeFileSync(
  join(root, 'src/ui/terminalHtml.generated.ts'),
  `// Generated by scripts/build-terminal-html.mjs. Do not edit.\nexport const TERMINAL_HTML = ${JSON.stringify(html)};\n`,
);
console.log(`terminal html: ${(html.length / 1024).toFixed(0)} KB`);
